create table if not exists public.myryra_finance_delivery_log (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, notification_id uuid not null references public.myryra_finance_notifications(id) on delete cascade, channel text not null check(channel in ('email','push')), status text not null default 'pending' check(status in ('pending','sent','failed','cancelled')), attempts integer not null default 0, created_at timestamptz not null default now(), unique(notification_id,channel)); alter table public.myryra_finance_delivery_log enable row level security; create policy finance_delivery_log_own on public.myryra_finance_delivery_log for select to authenticated using ((select auth.uid())=user_id); grant select on public.myryra_finance_delivery_log to authenticated;